import Foundation

struct Book {
    let id: Int
    let title: String
    var borrower: String? = nil
    var isAvailable: Bool { borrower == nil }
}

struct Library {
    private(set) var books: [Book] = []
    mutating func add(_ book: Book) { books.append(book) }
    func search(_ query: String) -> [Book] {
        books.filter { $0.title.localizedCaseInsensitiveContains(query) }
    }
    mutating func borrow(bookID: Int, by borrower: String) -> Bool {
        guard !borrower.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
              let index = books.firstIndex(where: { $0.id == bookID && $0.isAvailable }) else { return false }
        books[index].borrower = borrower
        return true
    }
}

var library = Library()
library.add(Book(id: 1, title: "Swift Basics"))
print(library.search("swift").count)
print(library.borrow(bookID: 1, by: "Asha"))
print(library.books[0].isAvailable)
